/**
 * Phase 11.4 — news headline / article repetition audit (PRIORITY 9).
 * Advances a multi-year simulation and samples real media outputs.
 *
 * Run:
 *   pnpm --filter @lorsain/content-loader exec tsx ../../scripts/phase11_4-repetition-audit.mjs
 * Output:
 *   docs/qa/phase11_4/repetition-audit.json
 *   docs/qa/phase11_4/news-repetition-audit.md (summary regenerated by this script)
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { createSimulation } from "../packages/sim/src/engine.js";
import { advanceIntegrated, loadTerenaWorld } from "../packages/sim/src/integration/harness.js";
import {
  ARTICLE_STRUCTURES,
  articleStructureFor,
  headlineFor,
} from "../packages/sim/src/media/index.js";
import { assignCrisisTheme } from "../packages/sim/src/foreign/crisis-emergence.js";
import { constitutionAlternativesFor } from "../packages/sim/src/provinces/constitutionAlternatives.js";
import {
  CONSTITUTIONAL_RULE_IDS,
  PROVINCIAL_BILL_SUBJECTS,
} from "../packages/sim/src/provinces/types.js";
import { CAMPAIGN_SITUATIONS } from "../packages/sim/src/campaigns/situations.js";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const OUT_JSON = resolve(repoRoot, "docs/qa/phase11_4/repetition-audit.json");
const OUT_MD = resolve(repoRoot, "docs/qa/phase11_4/news-repetition-audit.md");

function normalize(text) {
  return String(text ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function structuralKey(text) {
  return normalize(text)
    .replace(/\b(20\d{2}|npc\d+|act|bill|province|party)\b/g, "#")
    .replace(/\b\d+\b/g, "#");
}

function headlineFamily(story) {
  const type = String(story.factEventType ?? "UNKNOWN");
  const stem = type
    .toLowerCase()
    .split("_")
    .filter(Boolean)
    .slice(0, 2)
    .join("_");
  return `${story.category ?? "politics"}:${stem}`;
}

function tally(items) {
  const exact = new Map();
  const structural = new Map();
  for (const item of items) {
    const n = normalize(item);
    const s = structuralKey(item);
    exact.set(n, (exact.get(n) ?? 0) + 1);
    structural.set(s, (structural.get(s) ?? 0) + 1);
  }
  const exactDupes = [...exact.values()].filter((c) => c > 1).reduce((a, b) => a + (b - 1), 0);
  const structuralDupes = [...structural.values()]
    .filter((c) => c > 1)
    .reduce((a, b) => a + (b - 1), 0);
  return {
    total: items.length,
    uniqueExact: exact.size,
    uniqueStructural: structural.size,
    exactDuplicateExtras: exactDupes,
    structuralDuplicateExtras: structuralDupes,
  };
}

function cooldownDupes(items, windowSize = 8) {
  let hits = 0;
  const recent = [];
  for (const item of items) {
    const key = normalize(item);
    if (recent.includes(key)) hits += 1;
    recent.push(key);
    if (recent.length > windowSize) recent.shift();
  }
  return hits;
}

function distribution(items) {
  const map = new Map();
  for (const item of items) {
    map.set(item, (map.get(item) ?? 0) + 1);
  }
  return [...map.entries()]
    .map(([key, count]) => ({ key, count }))
    .sort((a, b) => b.count - a.count || a.key.localeCompare(b.key));
}

function blankRuntime(over = {}) {
  return {
    countryId: "A",
    leaderId: null,
    posture: "normal",
    capabilities: {
      economic: 0.5,
      land: 0.5,
      air: 0.5,
      naval: 0.5,
      strategic: 0.5,
      cyber: 0.5,
      logistics: 0.5,
    },
    tradeExposure: 0.3,
    strategicGoals: [],
    institutionIds: [],
    activeSanctionIds: [],
    governmentStability: 0.6,
    economicCapacity: 0.5,
    economicTrend: 0,
    domesticPressure: 0.2,
    metadata: {},
    ...over,
  };
}

function blankRelation(over = {}) {
  return {
    general: -5,
    trust: 0.4,
    securityTension: 0.1,
    economicTies: 0.2,
    lastUpdated: null,
    ...over,
  };
}

function main() {
  const world = loadTerenaWorld();
  const player =
    world.startingTerms.find((term) => world.offices[term.officeId]?.kind === "assembly_member")
      ?.holderId ?? world.startingTerms[0]?.holderId;
  if (!player) throw new Error("No player politician available");

  const sim = createSimulation({
    world,
    playerPoliticianId: player,
    seed: "P114-REPETITION-AUDIT-2030",
  });

  const months = 36;
  const storyHeadlines = [];
  const regenerated = [];
  const crisisThemes = [];
  const seenStoryIds = new Set();
  const families = [];
  const outlets = [];
  const categories = [];
  const structures = [];

  for (let i = 0; i < months; i += 1) {
    advanceIntegrated(sim, 1);
    const snap = sim.getSnapshot();
    for (const story of Object.values(snap.mediaRuntime?.stories ?? {})) {
      if (!story?.id || seenStoryIds.has(story.id)) continue;
      seenStoryIds.add(story.id);
      if (typeof story.headlineKey === "string" && story.headlineKey.trim()) {
        storyHeadlines.push(story.headlineKey);
      }
      regenerated.push(
        headlineFor(story.factEventType ?? "UNKNOWN", story.framing ?? "restrained", {
          title: story.headlineKey,
        }),
      );
      families.push(headlineFamily(story));
      outlets.push(story.outletId ?? "unknown");
      categories.push(story.category ?? "politics");
      const stored = story.publicEffects?.bodyStructure;
      structures.push(
        typeof stored === "string" && ARTICLE_STRUCTURES.includes(stored)
          ? stored
          : articleStructureFor(story),
      );
    }
  }

  const postures = [
    {
      a: blankRuntime({
        posture: "mobilized",
        strategicGoals: ["maritime_access"],
        capabilities: { ...blankRuntime().capabilities, naval: 0.7 },
      }),
      b: blankRuntime({ countryId: "B" }),
      rel: blankRelation(),
      neighbors: true,
      sanctions: false,
    },
    {
      a: blankRuntime(),
      b: blankRuntime({ countryId: "B" }),
      rel: blankRelation({ economicTies: 0.55 }),
      neighbors: false,
      sanctions: true,
    },
    {
      a: blankRuntime(),
      b: blankRuntime({ countryId: "B" }),
      rel: blankRelation({ economicTies: 0.55 }),
      neighbors: false,
      sanctions: false,
    },
    {
      a: blankRuntime(),
      b: blankRuntime({ countryId: "B" }),
      rel: blankRelation({ general: -30, securityTension: 0.4 }),
      neighbors: false,
      sanctions: false,
    },
    {
      a: blankRuntime(),
      b: blankRuntime({ countryId: "B" }),
      rel: blankRelation(),
      neighbors: true,
      sanctions: false,
    },
  ];
  for (let i = 0; i < 40; i += 1) {
    const p = postures[i % postures.length];
    crisisThemes.push(assignCrisisTheme(p.a, p.b, p.rel, p.neighbors, p.sanctions));
  }

  const campaignSituationTitles = CAMPAIGN_SITUATIONS.flatMap((s) => s.titles);
  const bannedFragments = [
    "viral debate",
    "debate aftermath",
    "election-eve rally",
    "dark-money",
    "doubled volunteer",
    "diplomatic expulsion",
    "naval confrontation",
    "trade corridor closure",
  ];
  const bannedHits = [...storyHeadlines, ...campaignSituationTitles].filter((text) =>
    bannedFragments.some((frag) => normalize(text).includes(normalize(frag))),
  );

  const mediaStats = {
    ...tally(storyHeadlines),
    cooldownWindowDupes: cooldownDupes(storyHeadlines, 8),
    sample: storyHeadlines.slice(0, 16),
    headlineFamilies: distribution(families).slice(0, 20),
    outlets: distribution(outlets),
    categories: distribution(categories),
    articleStructures: distribution(structures),
  };

  const report = {
    generatedAt: new Date().toISOString(),
    seed: "P114-REPETITION-AUDIT-2030",
    monthsAdvanced: months,
    mediaStories: mediaStats,
    regeneratedHeadlines: {
      ...tally(regenerated),
      cooldownWindowDupes: cooldownDupes(regenerated, 8),
    },
    crisisThemes: {
      ...tally(crisisThemes),
      distribution: [
        ...crisisThemes
          .reduce((map, theme) => {
            map.set(theme, (map.get(theme) ?? 0) + 1);
            return map;
          }, new Map())
          .entries(),
      ].map(([theme, count]) => ({ theme, count })),
    },
    campaignSituations: {
      templateCount: CAMPAIGN_SITUATIONS.length,
      titleCount: campaignSituationTitles.length,
      ...tally(campaignSituationTitles),
      sample: campaignSituationTitles.slice(0, 12),
    },
    provincialBillSubjects: {
      total: PROVINCIAL_BILL_SUBJECTS.length,
      ids: [...PROVINCIAL_BILL_SUBJECTS],
    },
    constitutionAlternatives: Object.fromEntries(
      CONSTITUTIONAL_RULE_IDS.map((ruleId) => [
        ruleId,
        constitutionAlternativesFor(ruleId).map((alt) => ({
          value: alt.value,
          label: alt.label,
        })),
      ]),
    ),
    narrativeTruthSpotCheck: {
      bannedFragmentHits: bannedHits.length,
      bannedHits: bannedHits.slice(0, 10),
    },
    notes: [
      "mediaStories are unique story.headlineKey values accumulated across the run.",
      "Cooldown keys cover exact (x:), structural (s:), and event-wording (w:) fingerprints.",
      "Article structures are consequence_first | event_first | institutional | political_reaction | regional.",
      "Exact duplicates remain acceptable for recurring institutional beats across long runs; recent-window dupes are the primary regression signal.",
    ],
  };

  mkdirSync(dirname(OUT_JSON), { recursive: true });
  writeFileSync(OUT_JSON, `${JSON.stringify(report, null, 2)}\n`, "utf8");

  const md = `# News repetition audit (Phase 11.4 / PRIORITY 9)

Generated: ${report.generatedAt}

## Method

- Seed: \`${report.seed}\`
- Advance integrated Terena world **${months} months**
- Collect each media story once (by story id)
- Metrics: total / unique exact / unique structural / extras / **recent-window (8) exact duplicates**
- Distributions: headline family (\`category:eventStem\`), outlet, category, article body structure

Re-run:

\`\`\`bash
pnpm --filter @lorsain/content-loader exec tsx ../../scripts/phase11_4-repetition-audit.mjs
\`\`\`

## Results (this run)

| Metric | Value |
| --- | ---: |
| Total stories | ${mediaStats.total} |
| Unique exact | ${mediaStats.uniqueExact} |
| Unique structural | ${mediaStats.uniqueStructural} |
| Exact duplicate extras | ${mediaStats.exactDuplicateExtras} |
| Structural duplicate extras | ${mediaStats.structuralDuplicateExtras} |
| Recent-window (8) exact dupes | ${mediaStats.cooldownWindowDupes} |
| Banned narrative fragments | ${report.narrativeTruthSpotCheck.bannedFragmentHits} |

### Headline families (top)

${mediaStats.headlineFamilies
  .slice(0, 12)
  .map((row) => `- \`${row.key}\`: ${row.count}`)
  .join("\n")}

### Outlets

${mediaStats.outlets.map((row) => `- \`${row.key}\`: ${row.count}`).join("\n")}

### Categories

${mediaStats.categories.map((row) => `- \`${row.key}\`: ${row.count}`).join("\n")}

### Article body structures

${mediaStats.articleStructures.map((row) => `- \`${row.key}\`: ${row.count}`).join("\n")}

### Sample headlines

${mediaStats.sample.map((h) => `- ${h}`).join("\n")}

## Interpretation

- Prefer **recent-window duplicates** near zero; long-run exact extras can still rise when the same institutional beat recurs months apart.
- Structural unique should track closer to exact unique after template diversity work.
- Full JSON: \`docs/qa/phase11_4/repetition-audit.json\`
`;

  writeFileSync(OUT_MD, md, "utf8");
  console.log("wrote", OUT_JSON);
  console.log("wrote", OUT_MD);
  console.log(
    JSON.stringify(
      {
        stories: report.mediaStories.total,
        uniqueExact: report.mediaStories.uniqueExact,
        uniqueStructural: report.mediaStories.uniqueStructural,
        exactDupExtras: report.mediaStories.exactDuplicateExtras,
        structuralDupExtras: report.mediaStories.structuralDuplicateExtras,
        cooldownWindowDupes: report.mediaStories.cooldownWindowDupes,
        bannedHits: report.narrativeTruthSpotCheck.bannedFragmentHits,
      },
      null,
      2,
    ),
  );
}

main();
